style.css:
@-moz-document domain("roblox.com") {
/* Fondo general */
  html, body {
    background-image: url("https://i.imgur.com/W1fXR40.jpeg") !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-color: transparent !important;
  }

  /* Hace transparente todo lo que cubre el fondo */
  .dark-theme, .theme-dark, .light-theme, .theme-light,
  .rbx-body, .app-container, .content, .page-content,
  .home-container, .col-xs-12, .section, .container-main,
  .main-content, .body-container, #container-main, #container-body {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* Quita filtros, opacidad o sombras */
  * {
    backdrop-filter: none !important;
    box-shadow: none !important;
  }

  /* Textos visibles sobre la imagen */
  body, h1, h2, h3, h4, h5, p, span, a, div {
    color: #ffffff !important;
  }
}
